package dev.aster.cosmetics;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.TextFieldWidget;
import net.minecraft.text.Text;
import java.util.*;
import java.util.function.*;
public final class AsterSettingsScreen extends Screen {
 private final Screen parent; private int scroll=0; private int objectIndex=0; private int tab=0,px=-1,py=22,pw=260,ph; private double ox,oy; private boolean moving; private CosmeticConfig.Widget dragged;private int dw,dh;private DoubleConsumer slider;private final List<Row> rows=new ArrayList<>();
 private record Row(int x,int y,int w,int h,Runnable click,DoubleConsumer slide){}
 public AsterSettingsScreen(Screen p){super(Text.literal("Aster Studio"));parent=p;}
 @Override protected void init(){if(px<0)px=Math.max(8,width-276);ph=Math.min(height-44,330);buildFields();}
 private void buildFields(){clearChildren();if(tab==3 && !AsterClient.CONFIG.sky.bodies.isEmpty()){var list=AsterClient.CONFIG.sky.bodies;objectIndex=Math.min(objectIndex,list.size()-1);var body=list.get(objectIndex);TextFieldWidget color=new TextFieldWidget(textRenderer,px+128,py+282-scroll,110,18,Text.literal("Object color"));color.setMaxLength(7);color.setText(body.color);color.setChangedListener(v->{if(v.matches("#[0-9a-fA-F]{6}"))body.color=v;});addDrawableChild(color);return;}if(tab!=2)return;var c=AsterClient.CONFIG;String[] labels={"HUD accent","Panel","Text","Buttons","Sky","Stars","Meteors"};String[] vals={c.hud.accent,c.ui.background,c.ui.text,c.ui.button,c.sky.color,c.sky.starColor,c.sky.meteorColor};for(int i=0;i<7;i++){final int k=i;TextFieldWidget f=new TextFieldWidget(textRenderer,px+128,py+60-scroll+i*25,110,18,Text.literal(labels[i]));f.setMaxLength(7);f.setText(vals[i]);f.setChangedListener(v->{if(!v.matches("#[0-9a-fA-F]{6}"))return;switch(k){case 0->c.hud.accent=v;case 1->c.ui.background=v;case 2->c.ui.text=v;case 3->c.ui.button=v;case 4->c.sky.color=v;case 5->c.sky.starColor=v;case 6->c.sky.meteorColor=v;}});addDrawableChild(f);}}
 private void row(DrawContext d,String label,String value,int y,Runnable action){d.drawText(textRenderer,label,px+16,y+6,CosmeticConfig.rgb(AsterClient.CONFIG.ui.text),false);d.drawText(textRenderer,value,px+175,y+6,AsterClient.CONFIG.accent(),false);rows.add(new Row(px+10,y,pw-20,22,action,null));}
 private void range(DrawContext d,String label,double v,double lo,double hi,int y,DoubleConsumer set){row(d,label,String.format(Locale.ROOT,"%.1f",v),y,()->{});d.fill(px+16,y+20,px+pw-16,y+22,0x443F4E66);d.fill(px+16,y+20,px+16+(int)((pw-32)*(v-lo)/(hi-lo)),y+22,AsterClient.CONFIG.accent());rows.add(new Row(px+16,y,pw-32,24,()->{},t->set.accept(lo+t*(hi-lo))));}
 @Override public void render(DrawContext d,int mx,int my,float delta){rows.clear();var c=AsterClient.CONFIG;d.fill(0,0,width,height,0x45202735);AsterHud.render(d,true);AsterHud.panel(d,px,py,pw,ph,0xF0000000|CosmeticConfig.rgb(c.ui.background)&0xFFFFFF);d.drawText(textRenderer,"ASTER STUDIO",px+16,py+13,c.accent(),false);d.drawText(textRenderer,"Drag header / Esc saves",px+110,py+13,CosmeticConfig.rgb(c.ui.text),false);String[] tabs={"HUD","Sky","Colors","Objects"};for(int i=0;i<4;i++){final int t=i;int x=px+12+i*60;d.fill(x,py+34,x+56,py+52,tab==i?c.accent():0x442A3549);d.drawCenteredTextWithShadow(textRenderer,tabs[i],x+28,py+39,tab==i?0xFF121725:CosmeticConfig.rgb(c.ui.text));rows.add(new Row(x,py+34,56,18,()->{tab=t;scroll=0;buildFields();},null));}
 d.enableScissor(px,py+54,px+pw,py+ph-3); int y=py+60-scroll;
 if(tab==0){row(d,"Custom HUD",c.hud.enabled?"On":"Off",y,()->c.hud.enabled=!c.hud.enabled);row(d,"FPS",c.hud.fps.enabled?"On":"Off",y+25,()->c.hud.fps.enabled=!c.hud.fps.enabled);row(d,"Coordinates",c.hud.coordinates.enabled?"On":"Off",y+50,()->c.hud.coordinates.enabled=!c.hud.coordinates.enabled);row(d,"Keystrokes",c.hud.keystrokes.enabled?"On":"Off",y+75,()->c.hud.keystrokes.enabled=!c.hud.keystrokes.enabled);row(d,"Crosshair",c.hud.crosshair.enabled?"On":"Off",y+100,()->c.hud.crosshair.enabled=!c.hud.crosshair.enabled);range(d,"HUD scale",c.hud.scale,.5,2,y+130,v->c.hud.scale=v);range(d,"Panel opacity",c.hud.opacity,.1,1,y+160,v->c.hud.opacity=v);}
 if(tab==1){row(d,"Replace sky",c.sky.preset,y,()->c.sky.preset=c.sky.preset.equals("vanilla")?"midnight":"vanilla");row(d,"Aurora",c.sky.preset.equals("aurora")?"On":"Off",y+25,()->c.sky.preset=c.sky.preset.equals("aurora")?"midnight":"aurora");row(d,"Shooting stars",c.sky.shootingStars?"On":"Off",y+50,()->c.sky.shootingStars=!c.sky.shootingStars);range(d,"Star density",c.sky.starDensity,0,1,y+80,v->c.sky.starDensity=v);range(d,"Meteor amount",c.sky.meteorFrequency,0,1,y+110,v->c.sky.meteorFrequency=v);range(d,"Meteor size",c.sky.meteorSize,.2,5,y+140,v->c.sky.meteorSize=v);}
 if(tab==2){String[] labels={"HUD accent","Panel","Text","Buttons","Sky","Stars","Meteors"};for(int i=0;i<7;i++)d.drawText(textRenderer,labels[i],px+16,y+5+i*25,CosmeticConfig.rgb(c.ui.text),false);}
 if(tab==3){row(d,"Add moon","+",y,()->{c.sky.bodies.add(new CosmeticConfig.Body());objectIndex=c.sky.bodies.size()-1;buildFields();});row(d,"Add sun","+",y+25,()->{var b=new CosmeticConfig.Body();b.name="Sun";b.color="#FFD27A";b.azimuth=-40;b.elevation=25;c.sky.bodies.add(b);objectIndex=c.sky.bodies.size()-1;buildFields();});if(!c.sky.bodies.isEmpty()){objectIndex=Math.min(objectIndex,c.sky.bodies.size()-1);var b=c.sky.bodies.get(objectIndex);row(d,b.name,b.enabled?"On":"Off",y+55,()->{objectIndex=(objectIndex+1)%c.sky.bodies.size();buildFields();});range(d,"Azimuth",b.azimuth,-180,180,y+85,v->b.azimuth=v);range(d,"Elevation",b.elevation,0,90,y+115,v->b.elevation=v);range(d,"Size",b.size,1,30,y+145,v->b.size=v);row(d,"Remove selected","Remove",y+180,()->{c.sky.bodies.remove(objectIndex);objectIndex=Math.max(0,objectIndex-1);buildFields();});}}
 if(tab==3&&!c.sky.bodies.isEmpty())d.drawText(textRenderer,"Object color",px+16,py+287-scroll,CosmeticConfig.rgb(c.ui.text),false);super.render(d,mx,my,delta);d.disableScissor();}
 @Override public boolean mouseClicked(double x,double y,int b){if(super.mouseClicked(x,y,b))return true;if(b!=0)return false;if(x>=px&&x<px+pw&&y>=py&&y<py+30){moving=true;ox=x-px;oy=y-py;return true;}for(int i=rows.size()-1;i>=0;i--){var r=rows.get(i);if(r.y>=py+54 && (y<py+54||y>=py+ph-3))continue;if(x>=r.x&&x<r.x+r.w&&y>=r.y&&y<r.y+r.h){if(r.slide!=null){slider=r.slide;ox=r.x;oy=r.w;slider.accept(CosmeticConfig.clamp((x-ox)/oy,0,1));}else r.click.run();return true;}}if(x>=px&&x<px+pw&&y>=py&&y<py+ph)return true;for(var box:AsterHud.boxes(width,height))if(x>=box.x()&&x<=box.x()+box.width()&&y>=box.y()&&y<=box.y()+box.height()){dragged=box.widget();dw=box.width();dh=box.height();ox=x-box.x();oy=y-box.y();return true;}return false;}
 @Override public boolean mouseDragged(double x,double y,int b,double dx,double dy){if(moving){px=(int)CosmeticConfig.clamp(x-ox,0,Math.max(0,width-pw));py=(int)CosmeticConfig.clamp(y-oy,0,Math.max(0,height-60));buildFields();return true;}if(slider!=null){slider.accept(CosmeticConfig.clamp((x-ox)/oy,0,1));return true;}if(dragged!=null){dragged.x=CosmeticConfig.clamp((x-ox)/Math.max(1,width-dw),0,1);dragged.y=CosmeticConfig.clamp((y-oy)/Math.max(1,height-dh),0,1);return true;}return super.mouseDragged(x,y,b,dx,dy);}
 @Override public boolean mouseReleased(double x,double y,int b){moving=false;slider=null;dragged=null;return super.mouseReleased(x,y,b);}
 @Override public boolean mouseScrolled(double x,double y,double horizontal,double vertical){if(x>=px&&x<px+pw){scroll=(int)CosmeticConfig.clamp(scroll-vertical*20,0,Math.max(0,330-ph));buildFields();return true;}return super.mouseScrolled(x,y,horizontal,vertical);}
 @Override public void close(){AsterClient.CONFIG.save();client.setScreen(parent);}
 @Override public boolean shouldPause(){return false;}
 @Override public void renderBackground(DrawContext d,int x,int y,float delta){}
 @Override public void removed(){AsterClient.CONFIG.save();}
}
